PROGRAM Main
VAR
    Permissive : BOOL;
    TripA : BOOL;
    TripB : BOOL;
    TripC : BOOL;
    VoteTrip : BOOL;
    Pressure : REAL := 0.0;
    HighPressureLimit : REAL := 100.0;
    HighPressureAlarm : BOOL;
    ManualMode : BOOL;
    ValveStatus1 : ValveStatus;
    ValveStatus2 : ValveStatus;
    ValveStatus3 : ValveStatus;
    PumpOn : BOOL;
    HeaterOn : BOOL;
    FanOn : BOOL;
    Setpoint : REAL := 80.0;
    LowLimit : REAL := 50.0;
    HighLimit : REAL := 120.0;
    PressureArray : ARRAY [1..5] OF REAL := [50.0, 60.0, 70.0, 80.0, 90.0];
    Index : INT := 1;
END_VAR

Setpoint := LIMIT(0.0, Setpoint, 100.0);
Permissive := (NOT TripA AND NOT TripB) AND (NOT TripA AND NOT TripC) AND (NOT TripB AND NOT TripC);
VoteTrip := (TripA AND TripB) OR (TripA AND TripC) OR (TripB AND TripC);
HighPressureAlarm := Pressure > HighPressureLimit;
IF ManualMode THEN
    ValveStatus1.Open := TRUE;
    ValveStatus2.Open := TRUE;
    ValveStatus3.Open := TRUE;
    PumpOn := TRUE;
    HeaterOn := TRUE;
    FanOn := TRUE;
ELSE
    IF Permissive AND NOT VoteTrip AND NOT HighPressureAlarm THEN
        ValveStatus1.Open := TRUE;
        ValveStatus2.Open := TRUE;
        ValveStatus3.Open := TRUE;
        PumpOn := TRUE;
        HeaterOn := TRUE;
        FanOn := TRUE;
    ELSE
        ValveStatus1.Open := FALSE;
        ValveStatus2.Open := FALSE;
        ValveStatus3.Open := FALSE;
        PumpOn := FALSE;
        HeaterOn := FALSE;
        FanOn := FALSE;
    END_IF;
END_IF;

FOR Index := 1 TO 5 DO
    PressureArray[Index] := PressureArray[Index] + 1.0;
END_FOR;

(* Safety overrides *)
IF VoteTrip THEN
    ValveStatus1.Open := FALSE;
    ValveStatus2.Open := FALSE;
    ValveStatus3.Open := FALSE;
    PumpOn := FALSE;
    HeaterOn := FALSE;
    FanOn := FALSE;
END_IF;

IF HighPressureAlarm THEN
    ValveStatus1.Open := FALSE;
    ValveStatus2.Open := FALSE;
    ValveStatus3.Open := FALSE;
    PumpOn := FALSE;
    HeaterOn := FALSE;
    FanOn := FALSE;
END_IF;

END_PROGRAM
